                    if r_title_norm != target_title_norm:
                        continue
                    r_artists = [a.get('name','') for a in r.get('artists', [])]
                    r_set = set([normalize_name(a) for a in r_artists])
                    if all(normalize_name(a) in r_set for a in artists):
