            else:
                resolved.append({
                    **ent,
                    'song_id': None,
                    'match_count': len(alt_unique),
                    'matched_title': None,
                    'matched_artists': None
                })
        else:
            resolved.append({
                **ent,
                'song_id': None,
                'match_count': len(unique_matches),
                'matched_title': None,
                'matched_artists': None
            })

print('Resolved count:', sum(1 for r in resolved if r.get('song_id') is not None), '/', len(resolved))

